-- Additive token issuer only. Existing business tables, triggers, RPC bodies and timeouts stay unchanged.
-- No staff/organization/ownership policies are introduced.
BEGIN;
DO $preflight$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='aka_agent_desktop')
    OR to_regclass('private.aka_agent_desktop_users') IS NOT NULL
    OR to_regprocedure('public.aka_agent_desktop_session_admin(text,jsonb)') IS NOT NULL
    OR to_regprocedure('public.aka_agent_desktop_login_content()') IS NOT NULL THEN
    RAISE EXCEPTION 'Desktop identity objects already exist; capture live state before editing';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.aka_agent_staff_time_allowed(bigint)')
    AND md5(pg_get_functiondef(oid))='a294e60011edd8d42e90ac2f74ce744c' AND prosecdef
    AND pg_get_userbyid(proowner)='postgres') THEN RAISE EXCEPTION 'Staff time guard changed'; END IF;
END;
$preflight$;
CREATE ROLE aka_agent_desktop NOLOGIN NOINHERIT NOBYPASSRLS;
-- Match the existing Desktop anon budget. Function-local bulk budgets stay intact.
ALTER ROLE aka_agent_desktop SET statement_timeout='3s';
ALTER ROLE aka_agent_desktop SET lock_timeout='8s';
GRANT aka_agent_desktop TO authenticator;
GRANT USAGE ON SCHEMA public,auth TO aka_agent_desktop;

CREATE TABLE private.aka_agent_desktop_users (
  staff_id bigint PRIMARY KEY REFERENCES public.org_staff(id) ON DELETE CASCADE,
  auth_user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE private.aka_agent_desktop_users ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.aka_agent_desktop_users FROM PUBLIC,anon,authenticated,service_role,aka_agent_desktop;

CREATE FUNCTION public.aka_agent_desktop_session_admin(p_operation text,p_data jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog SET statement_timeout='12s' SET lock_timeout='3s'
AS $function$
DECLARE s public.org_staff%ROWTYPE; uid uuid; sid uuid; email text; products jsonb;
BEGIN
  IF p_operation IS NULL OR p_operation NOT IN ('check','prepare','bind_user','register_session')
    OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'desktop_auth_invalid'; END IF;
  IF coalesce(p_data->>'username','')='' OR coalesce(p_data->>'password','')=''
    OR coalesce(p_data->>'fingerprintHash','') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'desktop_auth_invalid'; END IF;
  SELECT * INTO s FROM public.org_staff WHERE username=btrim(p_data->>'username') AND password=p_data->>'password' FOR SHARE;
  IF NOT FOUND OR NOT public.aka_agent_staff_time_allowed(s.id) THEN RAISE EXCEPTION 'desktop_auth_invalid'; END IF;
  IF p_operation='check' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',p.id,'product_id',p.product_id,'expiration_date',p.expiration_date,
      'package_type',p.package_type,'max_sends_per_day',p.max_sends_per_day,'max_accounts',p.max_accounts,
      'is_zalo_show_web',p.is_zalo_show_web,'is_zalo_server',p.is_zalo_server,'is_chat_sync',p.is_chat_sync,'created_at',p.created_at)
      ORDER BY p.created_at DESC NULLS LAST,p.id DESC),'[]'::jsonb) INTO products
      FROM public.org_organization_product p WHERE p.organization_id=s.organization_id AND p.is_deleted=false;
    RETURN jsonb_build_object('staffId',s.id,'organizationId',s.organization_id,'products',products);
  END IF;
  IF NOT s.is_policy_accepted OR s.aka_agent_device_identity_version<>3
    OR s.aka_agent_device_fingerprint_hash IS DISTINCT FROM p_data->>'fingerprintHash' THEN RAISE EXCEPTION 'desktop_device_invalid'; END IF;
  IF p_operation='bind_user' THEN
    uid:=(p_data->>'authUserId')::uuid;
    IF NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id=uid AND u.role='aka_agent_desktop'
      AND u.raw_app_meta_data->>'aka_agent_desktop'='true' AND u.email ~ '^[a-f0-9-]{36}@desktop-session[.]akaagent[.]invalid$') THEN
      RAISE EXCEPTION 'desktop_auth_identity_invalid';
    END IF;
    INSERT INTO private.aka_agent_desktop_users(staff_id,auth_user_id) VALUES(s.id,uid) ON CONFLICT(staff_id) DO NOTHING;
  END IF;
  SELECT u.auth_user_id,a.email INTO uid,email FROM private.aka_agent_desktop_users u
    JOIN auth.users a ON a.id=u.auth_user_id AND a.role='aka_agent_desktop' WHERE u.staff_id=s.id;
  IF p_operation='register_session' THEN
    sid:=(p_data->>'sessionId')::uuid;
    IF uid IS NULL OR uid IS DISTINCT FROM (p_data->>'authUserId')::uuid
      OR NOT EXISTS (SELECT 1 FROM auth.sessions a WHERE a.id=sid AND a.user_id=uid) THEN RAISE EXCEPTION 'desktop_auth_identity_invalid'; END IF;
  END IF;
  RETURN jsonb_build_object('staffId',s.id,'organizationId',s.organization_id,'authUserId',uid,'email',email);
END;
$function$;
REVOKE ALL ON FUNCTION public.aka_agent_desktop_session_admin(text,jsonb) FROM PUBLIC,anon,authenticated,service_role,aka_agent_desktop;
GRANT EXECUTE ON FUNCTION public.aka_agent_desktop_session_admin(text,jsonb) TO service_role;

-- Only this non-secret scalar is needed by the updater before login.
CREATE FUNCTION public.aka_agent_desktop_startup_policy() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $function$
  SELECT jsonb_build_object('value',value) FROM public.auto_system_settings
    WHERE key='desktop.updates.startup_prompt_max_version' AND is_active AND NOT is_secret;
$function$;
REVOKE ALL ON FUNCTION public.aka_agent_desktop_startup_policy() FROM PUBLIC,anon,authenticated,service_role,aka_agent_desktop;
GRANT EXECUTE ON FUNCTION public.aka_agent_desktop_startup_policy() TO anon,aka_agent_desktop,service_role;

-- The login screen needs only these five public settings before a token exists.
-- No arguments, arbitrary key lookup, staff data or table privileges are exposed.
CREATE FUNCTION public.aka_agent_desktop_login_content() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'key',key,'value',value,'updated_at',updated_at) ORDER BY key),'[]'::jsonb)
  FROM public.auto_system_settings
  WHERE key IN ('app.notification','akabiz.links.website','akabiz.links.user_guide',
    'akabiz.links.upgrade_payment','akabiz.links.contact_us')
    AND is_active=true AND is_secret=false;
$function$;
REVOKE ALL ON FUNCTION public.aka_agent_desktop_login_content() FROM PUBLIC,anon,authenticated,service_role,aka_agent_desktop;
GRANT EXECUTE ON FUNCTION public.aka_agent_desktop_login_content() TO anon,aka_agent_desktop,service_role;
