ated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arw/postgres}","options":null,"view":null},{"name":"zalo_accounts","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=r/postgres}","options":null,"view":null},{"name":"auto_account_contacts","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arw/postgres}","options":null,"view":null},{"name":"auto_media_files","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=rw/postgres}","options":null,"view":null},{"name":"v_sales_opp_overview","kind":"v","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":" SELECT o.id,\n    o.status,\n    o.closed_reason,\n    t.code AS type_code,\n    t.name AS type_name,\n    o.stage,\n    o.probability,\n    o.priority_score,\n    o.customer_id,\n    cu.name AS customer_name,\n    cu.phone AS customer_phone,\n    o.owner_org_staff_id,\n    st.name AS owner_name,\n    o.anchor_date,\n    o.trial_start_date,\n    (o.lifecycle_end_at AT TIME ZONE ''Asia/Ho_Chi_Minh''::text)::date AS het_vong_doi,\n    (o.lifecycle_end_at AT TIME ZONE ''Asia/Ho_Chi_Minh''::text)::date - fn_opp_today_vn() AS con_lai_ngay,\n    o.source_kind,\n    o.source_crm_id,\n    o.care_progress,\n    ( SELECT count(*) AS count\n           FROM aka_crm c\n          WHERE c.sales_opportunity_id = o.id AND c.source_type = ''sales_opp''::text) AS so_task_buoc,\n    ( SELECT count(*) AS count\n           FROM aka_crm c\n          WHERE c.sales_opportunity_id = o.id AND c.source_type = ''sales_opp''::text AND c.cskh_completed_date IS NOT NULL) AS so_task_da_lam,\n    o.next_action_type,\n    o.next_action_at,\n    o.actual_revenue,\n    o.created_at,\n    o.closed_at\n   FROM aka_salesopportunity o\n     JOIN aka_salesopportunity_type t ON t.id = o.type_id\n     JOIN aka_customer cu ON cu.id = o.customer_id\n     LEFT JOIN org_staff st ON st.id = o.owner_org_staff_id;"},{"name":"v_sales_opp_task_hom_nay","kind":"v","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":" SELECT c.id AS crm_id,\n    c.sales_opportunity_id AS opp_id,\n    c.gen_meta ->> ''type_code''::text AS type_code,\n    c.gen_meta ->> ''step_code''::text AS step_code,\n    c.gen_meta ->> ''actor''::text AS actor,\n    (c.gen_meta ->> ''manual_send''::text)::boolean AS nv_gui_tay,\n    c.gen_meta ->> ''segment''::text AS segment,\n    c.gen_meta ->> ''state''::text AS trial_state,\n    c.customer_id,\n    c.customer_name,\n    c.customer_phone,\n    c.org_staff_owner_id,\n    st.name AS owner_name,\n    c.suggested_channel_id,\n    c.priority,\n    (c.cskh_due_date AT TIME ZONE ''Asia/Ho_Chi_Minh''::text) AS han_vn,\n    c.gen_status,\n    c.cskh_completed_date,\n    c.suggested_content,\n    c.task_note,\n    c.pancake_url\n   FROM aka_crm c\n     LEFT JOIN org_staff st ON st.id = c.org_staff_owner_id\n  WHERE c.source_type = ''sales_opp''::text AND (c.cskh_due_date AT TIME ZONE ''Asia/Ho_Chi_Minh''::text)::date = fn_opp_today_vn();"},{"name":"ai_prompt","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=r/postgres,anon=r/postgres,authenticated=r/postgres}","options":null,"view":null},{"name":"auto_media_groups","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arw/postgres}","options":null,"view":null},{"name":"auto_media_group_items","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=ard/postgres}","options":null,"view":null},{"name":"auto_email_message_trackings","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_email_link_trackings","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_zalo_api_error_logs","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=a/postgres}","options":null,"view":null},{"name":"auto_account_action_status","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arw/postgres}","options":null,"view":null},{"name":"auto_account_contacts_dataset","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_account_contacts_dataset_members","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"chat_zalo_account","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arwd/postgres}","options":null,"view":null},{"name":"chat_zalo_account_tag","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arwd/postgres}","options":null,"view":null},{"name":"chat_zalo_account_user","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arwd/postgres}","options":null,"view":null},{"name":"auto_campaign_drafts","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_automation_actions","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,anon=r/postgres,authenticated=r/postgres}","options":null,"view":null},{"name":"auto_automation_data_types","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,anon=r/postgres,authenticated=r/postgres}","options":null,"view":null},{"name":"auto_automation_target_counters","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_automation_enqueue_failures","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_campaign_action_data_types","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,anon=r/postgres,authenticated=r/postgres}","options":null,"view":null},{"name":"auto_automation","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_automation_detail","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_account_contact_group_members","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=r/postgres}","options":null,"view":null},{"name":"v_trial_cham_14ngay","kind":"v","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":" WITH trial_raw AS (\n         SELECT o.customer_id,\n            o.date_create AS trial_at,\n            ''old''::text AS he_thong,\n            o.id AS ref_id,\n            o.account_id_old,\n            NULL::bigint AS organization_id,\n            o.product_list AS san_pham_goc,\n            o.username AS tai_khoan,\n                CASE\n                    WHEN o.product_list ~~* ''%sms%''::text AND o.product_list !~~* ''%zalo%''::text AND o.product_list !~~* ''%facebook%''::text AND o.product_list !~~* ''%fb%''::text THEN ''SMS''::text\n                    WHEN o.product_list ~~* ''%zalo%''::text AND o.product_list !~~* ''%facebook%''::text AND o.product_list !~~* ''%fb%''::text AND o.product_list !~~* ''%fanpage%''::text AND o.product_list !~~* ''%sms%''::text THEN ''Zalo''::text\n                    WHEN (o.product_list ~~* ''%facebook%''::text OR o.product_list ~~* ''%fbextension%''::text OR o.product_list ~~* ''%fanpage%''::text) AND o.product_list !~~* ''%zalo%''::text AND o.product_list !~~* ''%sms%''::text THEN ''Facebook''::text\n                    ELSE ''Combo''::text\n                END AS nhom\n           FROM aka_order o\n          WHERE o.package = ''demo''::text AND o.customer_id IS NOT NULL AND o.date_create >= ((now() AT TIME ZONE ''Asia/Ho_Chi_Minh''::text)::date - 15)\n        UNION ALL\n         SELECT g.customer_id,\n            q.created_at,\n            ''new''::text,\n            q.id,\n            NULL::integer,\n            q.organization_id,\n            q.product_name,\n            g.sql_account_id,\n                CASE\n                    WHEN q.product_name ~~* ''%facebook%''::text OR q.product_name ~~* ''%fanpage%''::text THEN ''Facebook''::text\n                    WHEN q.product_name ~~* ''%zalo%''::text THEN ''Zalo''::text\n                    WHEN q.product_name ~~* ''%sms%''::text THEN ''SMS''::text\n                    ELSE ''Combo''::text\n                END AS \"case\"\n           FROM org_organization_product q\n             JOIN org_organization g ON g.id = q.organization_id\n          WHERE q.package_type = ''demo''::text AND COALESCE(q.is_deleted, false) = false AND NOT COALESCE(q.is_paid, false) AND g.customer_id IS NOT NULL AND q.created_at >= ((now() AT TIME ZONE ''Asia/Ho_Chi_Minh''::text)::date - 15)\n        ), trial AS (\n         SELECT DISTINCT ON (trial_raw.customer_id, trial_raw.nhom) trial_raw.customer_id,\n            trial_raw.trial_at,\n            trial_raw.he_thong,\n            trial_raw.ref_id,\n            trial_raw.account_id_old,\n            trial_raw.organization_id,\n            trial_raw.san_pham_goc,\n            trial_raw.tai_khoan,\n            trial_raw.nhom\n           FROM trial_raw\n          ORDER BY trial_raw.customer_id, trial_raw.nhom, trial_raw.trial_at\n        ), base AS (\n         SELECT t.customer_id,\n            t.trial_at,\n            t.he_thong,\n            t.ref_id,\n            t.account_id_old,\n            t.organization_id,\n            t.san_pham_goc,\n            t.tai_khoan,\n            t.nhom,\n            a.name AS ten_khach,\n            a.phone,\n            NULLIF(a.email, ''''::text) AS email,\n            a.org_staff_id_owner,\n            a.inbox_url,\n            a.linh_vuc,\n            (now() AT TIME ZONE ''Asia/Ho_Chi_Minh''::text)::date - (t.trial_at AT TIME ZONE ''Asia/Ho_Chi_Minh''::text)::date AS ngay_thu,\n            fn_trang_thai_mua(t.customer_id) AS trang_thai_mua,\n            (EXISTS ( SELECT 1\n                   FROM aka_sale_order s\n                     JOIN aka_sale_order_item i ON i.sale_order_id = s.id\n                  WHERE s.customer_id = t.customer_id AND s.status = ''completed''::text AND s.paid_at >= (t.trial_at - ''01:00:00''::interval))) AS da_co_don,\n            a.decline_date IS NOT NULL AND a.decline_date >= t.trial_at AS da_tu_choi,\n                CASE\n                    WHEN t.he_thong = ''old''::text THEN (EXISTS ( SELECT 1\n                       FROM aka_tracking_app k\n                      WHERE k.account_id = t.account_id_old AND (k.event_type = ANY (ARRAY[''login''::text, ''login_app_akabiz''::text, ''open_app_akabiz''::text]))))\n                    ELSE (EXISTS ( SELECT 1\n                       FROM auto_accounts x\n                      WHERE x.organization_id = t.organization_id AND COALESCE(x.is_delete, false) = false))\n                END AS da_dang_nhap,\n                CASE\n                    WHEN t.he_thong = ''old''::text THEN (EXISTS ( SELECT 1\n                       FROM aka_tracking_app k\n                      WHERE k.account_id = t.account_id_old AND k.event_type = ''add''::text))\n                    ELSE (EXISTS ( SELECT 1\n                       FROM auto_campaigns k\n                      WHERE k.organization_id = t.organization_id AND k.created_at >= (t.trial_at - ''01:00:00''::interval)))\n                END AS da_chay_chien_dich,\n                CASE\n                    WHEN t.he_thong = ''old''::text THEN ( SELECT count(*) AS count\n                       FROM aka_tracking_app k\n                      WHERE k.account_id = t.account_id_old AND k.event_type = ''add''::text)\n                    ELSE ( SELECT count(*) AS count\n                       FROM auto_campaigns k\n                      WHERE k.organization_id = t.organization_id AND k.created_at >= (t.trial_at - ''01:00:00''::interval))\n                END AS so_chien_dich,\n            ( SELECT max(g.question_first_at) AS max\n                   FROM message_gom g\n                  WHERE g.aka_customer_id = t.customer_id AND g.initiated_by = ''CUSTOMER''::text AND COALESCE(g.question_content, ''''::text) <> ''''::text) AS tin_khach_cuoi\n           FROM trial t\n             JOIN aka_customer a ON a.id = t.customer_id\n        )\n SELECT customer_id,\n    ten_khach,\n    phone,\n    email,\n    nhom,\n    he_thong,\n    ref_id,\n    organization_id,\n    tai_khoan,\n    san_pham_goc,\n    trial_at,\n    ngay_thu,\n        CASE\n            WHEN ngay_thu = ANY (ARRAY[1, 2, 3, 5, 7, 10, 14]) THEN ngay_thu\n            ELSE NULL::integer\n        END AS moc,\n        CASE\n            WHEN da_chay_chien_dich THEN ''A''::text\n            WHEN da_dang_nhap THEN ''B''::text\n            ELSE ''C''::text\n        END AS nhanh,\n    trang_thai_mua,\n    da_co_don,\n    da_tu_choi,\n    da_dang_nhap,\n    da_chay_chien_dich,\n    so_chien_dich,\n    tin_khach_cuoi,\n    trang_thai_mua <> ''dang_dung''::text AND NOT da_co_don AND NOT da_tu_choi AS du_dieu_kien,\n    tin_khach_cuoi IS NULL OR tin_khach_cuoi < (now() - ''48:00:00''::interval) AS khach_im_lang_48h,\n    ngay_thu >= 5 AND (tin_khach_cuoi IS NULL OR tin_khach_cuoi < (now() - ''48:00:00''::interval)) AS gui_tu_dong,\n    org_staff_id_owner,\n    inbox_url,\n    linh_vuc\n   FROM base;"},{"name":"org_group_staff","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arwd/postgres}","options":null,"view":null},{"name":"chat_zalo_conversation_system_tag","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=ard/postgres}","options":null,"view":null},{"name":"auto_campaign_creation_bundles","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_campaign_data_group_sources","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_campaign_input_target_aliases","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"auto_campaign_input_origins","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"category_type","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,anon=r/postgres,authenticated=r/postgres,aka_agent_chat_api=r/postgres}","options":null,"view":null},{"name":"chat_zalo_account_conversation","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arwd/postgres}","options":null,"view":null},{"name":"chat_zalo_account_conversation_tag","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,aka_agent_chat_api=arwd/postgres}","options":null,"view":null},{"name":"category_item","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres,anon=r/postgres,authenticated=r/postgres,aka_agent_chat_api=r/postgres}","options":null,"view":null},{"name":"aka_crm_status","kind":"r","owner":"postgres","rls":false,"force":false,"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","options":null,"view":null},{"name":"chat_zalo_account_organization","kind":"r","owner":"postgres","rls":true,"force":false,"acl":"{postgres=arwdDxtm/pos