 SELECT * INTO c FROM pg_class WHERE oid=to_regclass(format('public.%I',r.name));
 IF NOT FOUND OR c.relkind::text<>r.kind OR pg_get_userbyid(c.relowner)<>r.owner OR c.relrowsecurity<>r.rls
 OR c.relforcerowsecurity<>r.force OR c.relacl::text IS DISTINCT FROM r.acl OR c.reloptions IS DISTINCT FROM r.options
